"""Cached bird dossiers generated by the local model or external APIs."""

import re
import threading
import time
from concurrent.futures import ThreadPoolExecutor
from typing import Any, Dict, Optional, Tuple

from django.conf import settings

from myapp.services.firebase_client import cache_bird_info, get_cached_bird_info
from myapp.services.local_model import generate_profile, is_available
from myapp.services.ncbi_source import fetch_ncbi
from myapp.services.species_sources import (
    fetch_gbif,
    fetch_inaturalist,
    fetch_wikipedia,
)

SCHEMA_VERSION = 5
_generation_lock = threading.Lock()
_generating: set[str] = set()
_generation_failures: Dict[str, float] = {}
FAILURE_COOLDOWN_SECONDS = 300


def common_name_from_label(class_label: str) -> str:
    """Converts a CUB label (``001.Black_footed_Albatross``) into a display name."""
    return class_label.split(".", 1)[-1].replace("_", " ").strip()


def species_slug(class_label: str) -> str:
    """Builds a stable, Firestore-safe cache key for a species label."""
    cleaned = common_name_from_label(class_label).lower()
    return re.sub(r"[^a-z0-9]+", "_", cleaned).strip("_")


def _cached(class_label: str) -> Tuple[str, Optional[Dict[str, Any]]]:
    slug = species_slug(class_label)
    cached = get_cached_bird_info(slug)
    if cached and cached.get("schema_version") == SCHEMA_VERSION:
        cached["cache_hit"] = True
        return slug, cached
    return slug, cached


def _empty_profile(class_label: str, reference: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    reference = reference or {}
    common_name = common_name_from_label(class_label)
    return {
        "schema_version": SCHEMA_VERSION,
        "label": class_label,
        "slug": species_slug(class_label),
        "common_name": reference.get("common_name") or common_name,
        "scientific_name": reference.get("scientific_name"),
        "summary": "",
        "habitat": "",
        "taxonomy": reference.get("taxonomy") or {},
        "iucn_status": reference.get("iucn_status"),
        "iucn_code": reference.get("iucn_code"),
        "native_range": reference.get("native_range") or [],
        "lifespan": {"wild_years": None, "captive_years": None},
        "chromosome_count_2n": None,
        "image_url": reference.get("image_url"),
        "image_attribution": reference.get("image_attribution"),
        "image_license": reference.get("image_license"),
        "wikipedia_url": reference.get("wikipedia_url"),
        "inaturalist_url": reference.get("inaturalist_url"),
        "gbif_url": reference.get("gbif_url"),
        "ncbi": reference.get("ncbi"),
        "source": "cache" if reference else "unavailable",
        "verified": bool(reference),
        "sources": reference.get("sources") or [],
        "cache_hit": False,
    }


def _external_profile(class_label: str, reference: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Legacy online enrichment path, retained for hybrid/external modes."""
    common_name = common_name_from_label(class_label)
    inaturalist = fetch_inaturalist(common_name)
    scientific_name = (inaturalist or {}).get("scientific_name") or (reference or {}).get(
        "scientific_name"
    )
    wikipedia = None
    gbif = None
    ncbi = None
    if scientific_name:
        with ThreadPoolExecutor(max_workers=3) as pool:
            wiki_future = pool.submit(fetch_wikipedia, common_name, scientific_name)
            gbif_future = pool.submit(fetch_gbif, scientific_name)
            ncbi_future = pool.submit(fetch_ncbi, scientific_name)
            wikipedia = wiki_future.result()
            gbif = gbif_future.result()
            ncbi = ncbi_future.result()
    else:
        wikipedia = fetch_wikipedia(common_name)

    profile = _empty_profile(class_label, reference)
    profile.update(
        {
            "common_name": (inaturalist or {}).get("common_name") or common_name,
            "scientific_name": scientific_name
            or (gbif or {}).get("accepted_name")
            or profile["scientific_name"],
            "summary": (wikipedia or {}).get("extract") or "",
            "taxonomy": (gbif or {}).get("taxonomy") or profile["taxonomy"],
            "iucn_status": (gbif or {}).get("iucn_status") or profile["iucn_status"],
            "iucn_code": (gbif or {}).get("iucn_code") or profile["iucn_code"],
            "native_range": (gbif or {}).get("native_range") or profile["native_range"],
            "image_url": (inaturalist or {}).get("photo_url")
            or (wikipedia or {}).get("image_url"),
            "image_attribution": (inaturalist or {}).get("photo_attribution"),
            "image_license": (inaturalist or {}).get("photo_license"),
            "wikipedia_url": (wikipedia or {}).get("url"),
            "inaturalist_url": (inaturalist or {}).get("url"),
            "gbif_url": (gbif or {}).get("url"),
            "ncbi": ncbi,
            "source": "external",
            "verified": True,
            "sources": [
                name
                for name, payload in (
                    ("wikipedia", wikipedia),
                    ("inaturalist", inaturalist),
                    ("gbif", gbif),
                    ("ncbi", ncbi),
                )
                if payload
            ],
        }
    )
    return profile


def _start_generation(class_label: str, reference: Optional[Dict[str, Any]]) -> None:
    slug = species_slug(class_label)
    with _generation_lock:
        if slug in _generating:
            return
        _generating.add(slug)

    def run() -> None:
        try:
            profile = generate_profile(class_label, reference)
            cache_bird_info(slug, dict(profile))
            with _generation_lock:
                _generation_failures.pop(slug, None)
        except Exception as exc:
            print(f"[WARNING] Local dossier generation failed for {class_label}: {exc}")
            with _generation_lock:
                _generation_failures[slug] = time.time()
        finally:
            with _generation_lock:
                _generating.discard(slug)

    threading.Thread(target=run, daemon=True, name=f"dossier-{slug}").start()


def fetch_species_profile(class_label: str) -> Dict[str, Any]:
    """Returns a dossier, generating and caching it synchronously when needed."""
    slug, cached = _cached(class_label)
    if cached and cached.get("schema_version") == SCHEMA_VERSION:
        return cached

    mode = settings.SPECIES_INFO_MODE
    if mode in ("local", "hybrid") and is_available():
        try:
            profile = generate_profile(class_label, cached)
            if mode == "hybrid":
                external = _external_profile(class_label, cached)
                external.update(
                    {
                        "summary": profile["summary"] or external["summary"],
                        "habitat": profile["habitat"],
                        "lifespan": profile["lifespan"],
                        "chromosome_count_2n": profile["chromosome_count_2n"],
                        "source": "hybrid",
                        "sources": sorted(set(external["sources"] + ["local-model"])),
                    }
                )
                profile = external
            cache_bird_info(slug, dict(profile))
            return profile
        except Exception as exc:
            print(f"[WARNING] Local dossier generation failed for {class_label}: {exc}")

    if mode != "local" or settings.SPECIES_EXTERNAL_ENRICHMENT:
        profile = _external_profile(class_label, cached)
        if profile["sources"]:
            cache_bird_info(slug, dict(profile))
        return profile

    return _empty_profile(class_label, cached)


def request_species_profile(
    class_label: str,
) -> Tuple[Optional[Dict[str, Any]], bool]:
    """
    Returns ``(profile, generating)`` for an HTTP request.
    Cache misses with the local model start a background generation job.
    """
    slug, cached = _cached(class_label)
    if cached and cached.get("schema_version") == SCHEMA_VERSION:
        return cached, False
    if settings.SPECIES_INFO_MODE in ("local", "hybrid") and is_available():
        with _generation_lock:
            failed_at = _generation_failures.get(slug)
        if failed_at and time.time() - failed_at < FAILURE_COOLDOWN_SECONDS:
            return _empty_profile(class_label, cached), False
        _start_generation(class_label, cached)
        return None, True
    return fetch_species_profile(class_label), False
